$fn = 96;

// ── Parameters ───────────────────────────────────────────
leaf_length   = 40;    // total hinge length along X (pin axis)
leaf_width    = 20;    // leaf plate width along Y
leaf_thick    = 3;     // plate thickness (Z)
pin_d         = 5;     // pin nominal diameter
wall          = 1.5;   // barrel wall around pin
knuckle_count = 5;     // total knuckles (odd)
clearance     = 0.35;  // print-in-place gap

// ── Derived ──────────────────────────────────────────────
knuckle_l   = leaf_length / knuckle_count;    // 8 mm — NOT leaf_length/(2*count-1)
knuckle_OD  = pin_d + 2 * wall;              // 8 mm
bore_a      = pin_d + clearance;             // 5.35 mm — leaf A hollow knuckle bore
bore_b      = pin_d + 2 * clearance;         // 5.7 mm  — leaf B (clearance for rotation)
n_a         = (knuckle_count + 1) / 2;       // 3
n_b         = (knuckle_count - 1) / 2;       // 2
knuckle_z   = leaf_thick + knuckle_OD / 2;  // Z of shared pin axis

// ── Leaf A: plate +Y, 3 pin knuckles ─────────────────────
// Pin axis: along X, at y=0, z=knuckle_z
// All cylinders: rotate([0,90,0]) — NOT rotate([90,0,0])
module hinge_leaf_a() {
    // Plate — positive Y side, clearance gap from hinge joint
    translate([0, clearance, 0])
        cube([leaf_length, leaf_width, leaf_thick]);

    // n_a=3 pin knuckles at x = k/2, 5k/2, 9k/2
    for (i = [0 : n_a - 1]) {
        x_c = (2*i) * knuckle_l + knuckle_l / 2;
        translate([x_c, 0, knuckle_z])
            rotate([0, 90, 0])
                difference() {
                    cylinder(h = knuckle_l - clearance, d = knuckle_OD, center = true);
                    cylinder(h = knuckle_l + 2, d = bore_a, center = true);
                }
    }
}

// ── Leaf B: plate -Y, 2 barrel knuckles ──────────────────
module hinge_leaf_b() {
    // Plate — negative Y side, clearance gap from hinge joint
    translate([0, -(leaf_width + clearance), 0])
        cube([leaf_length, leaf_width, leaf_thick]);

    // n_b=2 barrel knuckles at x = 3k/2, 7k/2
    for (i = [0 : n_b - 1]) {
        x_c = (2*i + 1) * knuckle_l + knuckle_l / 2;
        translate([x_c, 0, knuckle_z])
            rotate([0, 90, 0])
                difference() {
                    cylinder(h = knuckle_l - clearance, d = knuckle_OD, center = true);
                    cylinder(h = knuckle_l + 2,         d = bore_b,     center = true);
                }
    }
}

module five_knuckle_hinge() {
    hinge_leaf_a();
    hinge_leaf_b();
}

five_knuckle_hinge();

$fn = 96;

// Rectangular leaves left/right of a central barrel
// Countersunk screw holes
// Visible continuous pin
// Knurled finials
// Uses butt-hinge hardware layout, not print-in-place hinge layout

hinge_h     = 100;
leaf_w      = 38;
leaf_t      = 3;

barrel_d    = 12;
pin_d       = 5;

knuckle_gap = 0.4;
knuckle_len = hinge_h / 5 - knuckle_gap;

finial_len  = 10;
finial_d    = 10;
knurl_count = 32;

screw_d     = 5;
csk_d       = 9;
csk_depth   = 2;

module screw_hole() {
    rotate([90, 0, 0]) {
        cylinder(h = leaf_t + 2, d = screw_d, center = true);

        translate([0, 0, 0.45])
            cylinder(h = csk_depth, d1 = csk_d, d2 = screw_d, center = true);
    }
}

module leaf(side = 1) {
    x_center = side * (barrel_d / 2 + leaf_w / 2 - 0.25);
    screw_x  = side * (barrel_d / 2 + leaf_w * 0.55);

    difference() {
        translate([x_center, 0, hinge_h / 2])
            cube([leaf_w, leaf_t, hinge_h], center = true);

        for (z = [18, 50, 82])
            translate([screw_x, 0, z])
                screw_hole();
    }
}

module knuckle(len) {
    difference() {
        cylinder(h = len, d = barrel_d, center = false);
        translate([0, 0, -0.1])
            cylinder(h = len + 0.2, d = pin_d + 0.3, center = false);
    }
}

module knurled_finial() {
    difference() {
        cylinder(h = finial_len, d = finial_d, center = false);

        for (i = [0 : knurl_count - 1])
            rotate([0, 0, i * 360 / knurl_count])
                translate([finial_d / 2, 0, finial_len / 2])
                    cube([0.8, 0.8, finial_len + 2], center = true);
    }
}

module hinge() {
    leaf(-1);
    leaf(1);

    // visible continuous pin
    translate([0, 0, -finial_len])
        cylinder(h = hinge_h + 2 * finial_len, d = pin_d, center = false);

    // five barrel knuckles
    for (i = [0, 2, 4])
        translate([0, 0, i * hinge_h / 5 + knuckle_gap / 2])
            knuckle(knuckle_len);

    for (i = [1, 3])
        translate([0, 0, i * hinge_h / 5 + knuckle_gap / 2])
            knuckle(knuckle_len);

    // knurled finials
    translate([0, 0, hinge_h])
        knurled_finial();

    rotate([180, 0, 0])
        knurled_finial();
}

hinge();
